using System.Text.Json;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
internal static class WindowsEventSpecs
{
 public static void Run(string folder,Action<string,bool> check){var now=DateTime.UtcNow;var root=Path.Combine(folder,"windows-events");var events=new AgentEventStore(root);var network=new NetworkStore(root);bool Reject(Action a){try{a();return false;}catch(Exception e)when(e is ArgumentException or InvalidOperationException){return true;}}
 check("Journal standard policy valid",!Reject(()=>AgentEvents.Validate(new AgentEventPolicy())));
 check("Journal policy channel restricted",Reject(()=>AgentEvents.Validate(new AgentEventPolicy{Rules=[new(){Name="bad",Channel="Arbitrary",Provider="x",Ids=[1]}]})));
 check("Journal policy provider injection rejected",Reject(()=>AgentEvents.Validate(new AgentEventPolicy{Rules=[new(){Provider="x' or 1=1",Ids=[1]}]})));
 check("Journal rule thresholds bounded",Reject(()=>AgentEvents.Validate(new AgentEventPolicy{Rules=[new(){Provider="x",Ids=[1],Threshold=0}]})));
 check("Journal future events rejected",Reject(()=>AgentEvents.Validate(new AgentEventBatch("a",[new("k","System","x",1,1,now.AddDays(1),"x")],[]))));
 check("Journal security absent cannot be green",Reject(()=>AgentEvents.Validate(new AgentEventBatch("a",[],[new("Security","Absent","")]))));
 var query=System.Xml.Linq.XDocument.Parse(AgentEventQueries.Build("System",100,AgentEvents.Standard(),[]));check("Journal structured query has separate bounded selectors",query.Descendants("Select").Count()==AgentEvents.Standard().Count(r=>r.Channel=="System"));
 var securityQuery=AgentEventQueries.Build("Security",1,AgentEvents.Standard(),[]);check("Journal no normal-success stream without failed IP",!securityQuery.Contains("EventID=4624"));var correlated=AgentEventQueries.Build("Security",1,AgentEvents.Standard(),["192.0.2.1","invalid' or 1=1"]);check("Journal success query uses only validated IP",correlated.Contains("192.0.2.1")&&!correlated.Contains("invalid"));
 var eventXml=System.Xml.Linq.XElement.Parse("<Event><System><EventRecordID>101</EventRecordID><Provider Name='Microsoft-Windows-Kernel-Power'/><EventID>41</EventID></System></Event>");var expression=query.Descendants("Select").First().Value;check("Journal selector matches actual event XML",System.Xml.XPath.Extensions.XPathSelectElement(eventXml,"self::"+expression)!=null);
 check("Journal old protocol policy has unchanged shape",!JsonSerializer.Serialize(new AgentPolicy(),AgentWire.Json).Contains("Rules"));
 var policy=events.View(1).Policy;policy.Rules=[new(){Id="fail-login",Name="Неудачные входы",Channel="Security",Provider="Microsoft-Windows-Security-Auditing",Ids=[4625],Threshold=5,CriticalThreshold=20,QuietMinutes=60},new(){Id="logon-success",Name="Успех после ошибок",Channel="Security",Provider="Microsoft-Windows-Security-Auditing",Ids=[4624],Severity=Severity.Critical}];events.Save(new(1,policy,1));
 AgentJournalEvent Failed(int n,string ip="192.0.2.20")=>new("key"+n,"Security","Microsoft-Windows-Security-Auditing",4625,n,now.AddSeconds(n),"Неудачная попытка",ip);
 AgentEventBatch Batch(IEnumerable<AgentJournalEvent> list,string health="OK")=>new(Guid.NewGuid().ToString("N"),list.ToArray(),[new("Security",health,health)]);
 events.Ingest(1,Batch(Enumerable.Range(1,4).Select(n=>Failed(n))),null,false,now.AddSeconds(4));check("Four failures do not cross five-event threshold",events.View(1).Problems.Count==0);
 events.Ingest(1,Batch([Failed(5)]),null,false,now.AddSeconds(5));check("Fifth failure opens one warning",events.View(1).Problems is [{Open:true,Severity:Severity.Warning,Count:5}]);events.Flush(1,network);check("Journal opens notification through common Telegram outbox",network.State(s=>s.Notifications.Count)==1);
 events=new(root);events.Ingest(1,Batch([Failed(5)]),null,false,now.AddSeconds(6));events.Flush(1,network);check("Repeated batch after restart does not duplicate event or notification",events.View(1).Events.Count==5&&network.State(s=>s.Notifications.Count)==1);
 events.Ingest(1,Batch(Enumerable.Range(6,15).Select(n=>Failed(n))),null,false,now.AddSeconds(20));events.Flush(1,network);check("Failure escalation updates same incident",events.View(1).Problems is [{Severity:Severity.Critical,Count:20}]&&network.State(s=>s.Notifications.Count)==2);
 events.Ingest(1,Batch([Failed(21,"192.0.2.21")]),null,false,now.AddSeconds(21));check("Different failure sources increment one device incident",events.View(1).Problems is [{Count:21}]);
 events.Ingest(1,Batch([new("success","Security","Microsoft-Windows-Security-Auditing",4624,30,now.AddSeconds(30),"Успех","192.0.2.20")]),null,false,now.AddSeconds(30));check("Success after failed source raises review incident",events.View(1).Problems.Count==2);
 events.Ingest(1,Batch([Failed(31)]),null,false,now.AddMinutes(50));events.Ingest(1,Batch([]),null,false,now.AddMinutes(109));check("Quiet timer restarts on last attempt",events.View(1).Problems.Any(p=>p.RuleId=="fail-login"&&p.Open));events.Ingest(1,Batch([]),null,false,now.AddMinutes(111));check("Quiet period closes after sixty minutes",events.View(1).Problems.All(p=>p.RuleId!="fail-login"||!p.Open));
 events.Resolve(1,events.View(1).Problems.Single(p=>p.RuleId=="logon-success").Id);check("Manual resolution retains raw history",events.View(1).Problems.All(p=>!p.Open)&&events.View(1).Events.Count>20);
 var p2=events.View(2).Policy;p2.Rules=[new(){Id="fail-login",Name="Попытки входа",Channel="Security",Provider="Microsoft-Windows-Security-Auditing",Ids=[4625],QuietMinutes=60}];events.Save(new(2,p2,1));events.Ingest(2,Batch([Failed(80)]),null,true,now);check("Maintenance retains issue and suppresses notifications",events.View(2).Problems.Count==1&&events.View(2).Pending.Count==0);events.Ingest(2,Batch([]),null,false,now.AddMinutes(1));check("Maintenance completion notifies persistent problem once",events.View(2).Pending.Count==1);events.Flush(2,network);events.Flush(2,network);check("Journal outbox flush idempotent",network.State(s=>s.Notifications.Count(n=>n.EntityKey.StartsWith("journal:2:")))==1);
 events.Ingest(2,Batch([],"Denied"),null,false,now.AddHours(3));check("Unreadable log freezes quiet expiry",events.View(2).Problems.Any(p=>p.Open)&&events.Findings(2).Any(f=>f.Key.StartsWith("journal-reader:")));
 var updates=new OsUpdateStatus{State="Available",CheckedUtc=now,Installed="Windows",PendingCount=1,Items=["KB1234567"]};events.Ingest(3,null,updates,false,now);events.Ingest(3,null,updates,false,now.AddMinutes(1));check("Update availability remains silent",events.View(3).Pending.Count==0);events.Ingest(3,null,new(),false,now);events.Ingest(3,null,updates,false,now);check("Unknown update result does not create a notification",events.View(3).Pending.Count==0);check("Updates are not a health finding",events.Findings(3).All(f=>!f.Key.StartsWith("os-updates:")));
 var device=new Device{Id=1,Name="test",OsUpdatesJson=JsonSerializer.Serialize(updates)};var stamp=RemoteData.EntityStamp(device);device.OsUpdatesJson="{}";check("Update metadata cannot cause device edit conflict",RemoteData.EntityStamp(device)==stamp);
 check("Router versions compared numerically",RouterUpdateCatalog.Compare("7.9.2 (stable)","7.24.5",now).HasUpdates);check("Router no cross-major upgrade suggestion",RouterUpdateCatalog.Compare("6.49.18","7.24.5",now).State=="Unknown");check("Router same current version",RouterUpdateCatalog.Compare("7.24.5 (stable)","7.24.5",now).State=="Current");check("Unavailable catalog is not current",RouterUpdateCatalog.Compare("7.24.5","",null).State=="Unknown");check("Reboot required has separate update icon",new OsUpdateStatus{State="Current",RebootRequired=true}.HasUpdates);
 check("Role profiles valid",new[]{"SQL","AD","DNS"}.All(role=>!Reject(()=>AgentEvents.Validate(new AgentEventPolicy{Rules=AgentEvents.Role(role)}))));
 var p4=events.View(4).Policy;p4.Rules=[new(){Id="timeout",Name="Test",Channel="Security",Provider="Microsoft-Windows-Security-Auditing",Ids=[4625],QuietMinutes=60}];events.Save(new(4,p4,1));events.Ingest(4,Batch([Failed(100)]),null,false,now);var issue=events.View(4).Problems.Single().Id;events.Ingest(4,Batch([Failed(101)]),null,false,now.AddMinutes(61));check("New batch renews incident before quiet expiry",events.View(4).Problems.Single(p=>p.Open).Id==issue);
 check("Journal rejects stale configuration save",Reject(()=>events.Save(new(1,policy,1))));
 }
}
